head.script:
scwin.trigger1_onclick = function(e) {
    var focus_label = treeview1.getSelectedLabel();
    var sel_idx = treeview1.getSelectedIndex();
    //console.log( focus_label + "---" + sel_idx);
    var aa = dl_tree1.getMatchedData("menu_nm", focus_label);
    console.log("aa:" + aa);
    if (aa.length > 0) {
        return false;
    } else {
        var idx = dl_tree1.getRowCount();
        //console.log("idx:"+idx + "--- sel_idx:"+(sel_idx-1));
        var vobj = dl_tree.getRowJSON(sel_idx - 1);
        vobj.menu_no = 3;
        dl_tree1.setRowJSON(idx, vobj);
    }
};
scwin.trigger2_onclick = function(e) {
    var focus_label = treeview2.getSelectedLabel();
    var sel_idx = treeview2.getSelectedIndex();
    console.log("focus_label  " + focus_label);
    console.log("sel_idx  " + sel_idx);
    if (sel_idx == "") {
        return false;
    } else {
        dl_tree1.removeRow(sel_idx - 1);
    }
};
scwin.__isCheckLog = function() {
    return WebSquare.logger.getErrorLog() == "";
}
scwin.checkVal = function() {
    return typeof WebSquare.wUnit.getObjById('treeview2_label_3') == "object";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();

    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('treeview1_label_2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__isCheckLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('treeview2_label_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('treeview2').getSelectedLabel() == ''", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('treeview2').getSelectedIndex() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

