            "level": "2"
        },
        {
            "menu_no": 3,
            "menu_nm": "공통1-1",
            "level": "3"
        },
        {
            "menu_no": 4,
            "menu_nm": "수신",
            "level": "1"
        },
        {
            "menu_no": 5,
            "menu_nm": "수신1",
            "level": "2"
        },
        {
            "menu_no": 6,
            "menu_nm": "여신",
            "level": "1"
        },
        {
            "menu_no": 7,
            "menu_nm": "고객",
            "level": "1"
        }
    ];
    window.jsonData2 = [{
            "menu_no": 1,
            "menu_nm": "공통",
            "level": "1"
        },
        {
            "menu_no": 2,
            "menu_nm": "고객",
